def generateDiagram(project_id, input_spec, idempotency_key=None, generator_version=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0222000" if __import__("os").path.isdir("./environment_mix/0222000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        # 20 chars base32-ish, uppercase
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
        raw = uuid.uuid4().bytes + uuid.uuid4().bytes
        out = []
        for b in raw:
            out.append(alphabet[b & 31])
            if len(out) >= 20:
                break
        return f"{prefix}_{''.join(out)}"

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^ers_proj_[0-9A-Z]{18,}$", project_id):
        return _err("VALIDATION_ERROR", "Invalid project_id.")
    if not isinstance(input_spec, dict):
        return _err("VALIDATION_ERROR", "input_spec must be an object.")
    if idempotency_key is not None:
        if not isinstance(idempotency_key, str) or not (1 <= len(idempotency_key) <= 256):
            return _err("VALIDATION_ERROR", "Invalid idempotency_key.")
    if generator_version is not None:
        if not isinstance(generator_version, str) or not (1 <= len(generator_version) <= 128):
            return _err("VALIDATION_ERROR", "Invalid generator_version.")

    # Business rule: tool surface defines no parameters; normalize to {}
    normalized_input_spec = {}

    projects = _load("projects.json")
    gens = _load("diagram_generations.json")
    keys = _load("api_keys.json")
    usage = _load("usage_events.json")

    # Validate project exists and is not deleted (on delete restrict semantics for generations)
    proj = next((p for p in projects if p.get("id") == project_id), None)
    if not proj:
        # no generation_id to attach usage; return error
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)
    if proj.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "Cannot generate diagrams for a deleted project.", project_id=project_id)

    # Resolve an API key context if possible (ambient auth). Since this tool has no credential param,
    # choose a working active key if one exists; otherwise proceed as internal (api_key_id=None)
    active_keys = [k for k in keys if k.get("status") == "active"]
    api_key_row = active_keys[0] if active_keys else None
    api_key_id = api_key_row.get("id") if api_key_row else None

    # Idempotency: if idempotency_key supplied, return existing generation in same project
    if idempotency_key is not None:
        existing = next((g for g in gens if g.get("project_id") == project_id and g.get("idempotency_key") == idempotency_key), None)
        if existing:
            # Record usage event as accepted (idempotent attach)
            ue = {
                "id": _new_id("ers_usage"),
                "api_key_id": api_key_id,
                "generation_id": existing.get("id"),
                "tool_name": "generateDiagram",
                "request_ts": now_iso,
                "response_status": "accepted",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            usage.append(ue)
            _save("usage_events.json", usage)
            return {
                "generation": existing,
                "idempotent_replay": True,
            }

    # Apply rate limit and quota if we have an API key
    if api_key_row:
        # If key isn't active (shouldn't happen due to selection), reject
        if api_key_row.get("status") != "active":
            # can't enqueue; record usage error without generation_id: we must create a generation_id? Schema says generation_id non-null.
            # Therefore, create no usage event (cannot satisfy schema) and return UNAUTHORIZED-like error per business rule.
            return _err("UNAUTHORIZED", "API key is not active.")
        rate_limit = api_key_row.get("rate_limit_per_minute")
        quota = api_key_row.get("daily_generation_quota")
        if not isinstance(rate_limit, int) or rate_limit < 1 or rate_limit > 6000:
            return _err("UNAUTHORIZED", "API key misconfigured (rate limit).")
        if not isinstance(quota, int) or quota < 0 or quota > 100000:
            return _err("UNAUTHORIZED", "API key misconfigured (quota).")

        # Count accepted events in last 60 seconds
        cutoff = now - datetime.timedelta(seconds=60)
        accepted_recent = 0
        for e in usage:
            if e.get("api_key_id") != api_key_id: 
                continue
            if e.get("tool_name") != "generateDiagram" or e.get("response_status") != "accepted":
                continue
            ts = _parse_ts(e.get("request_ts"))
            if ts and ts >= cutoff:
                accepted_recent += 1
        if accepted_recent >= rate_limit:
            # Need a generation_id for usage event; but request rejected before enqueue, schema requires generation_id.
            # Real service would still log request; enforce schema by creating a placeholder generation with status=failed?
            # That would "enqueue" effect. Instead, refuse with RATE_LIMIT and do not write usage_event (cannot).
            return _err("RATE_LIMIT", "Rate limit exceeded.")

        # Count accepted events today UTC
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        accepted_today = 0
        for e in usage:
            if e.get("api_key_id") != api_key_id:
                continue
            if e.get("tool_name") != "generateDiagram" or e.get("response_status") != "accepted":
                continue
            ts = _parse_ts(e.get("request_ts"))
            if ts and ts >= day_start and ts <= now:
                accepted_today += 1
        if accepted_today >= quota:
            return _err("QUOTA_EXCEEDED", "Daily generation quota exceeded.")

    # Create generation
    gen_id = _new_id("ers_gen")
    gv = generator_version if generator_version is not None else "default"
    gen = {
        "id": gen_id,
        "project_id": project_id,
        "status": "queued",
        "requested_by_api_key_id": api_key_id,
        "generator_version": gv,
        "input_spec": normalized_input_spec,
        "idempotency_key": idempotency_key,
        "queued_at": now_iso,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "compute_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Enforce unique(project_id, idempotency_key) where not null (race-safe best effort)
    if idempotency_key is not None:
        for g in gens:
            if g.get("project_id") == project_id and g.get("idempotency_key") == idempotency_key:
                # Another entry exists; attach to it (idempotent)
                ue = {
                    "id": _new_id("ers_usage"),
                    "api_key_id": api_key_id,
                    "generation_id": g.get("id"),
                    "tool_name": "generateDiagram",
                    "request_ts": now_iso,
                    "response_status": "accepted",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }
                usage.append(ue)
                _save("usage_events.json", usage)
                return {"generation": g, "idempotent_replay": True}

    gens.append(gen)
    _save("diagram_generations.json", gens)

    # Record usage event accepted (now generation_id exists)
    ue = {
        "id": _new_id("ers_usage"),
        "api_key_id": api_key_id,
        "generation_id": gen_id,
        "tool_name": "generateDiagram",
        "request_ts": now_iso,
        "response_status": "accepted",
        "latency_ms": int((time.time() - t0) * 1000),
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    usage.append(ue)
    _save("usage_events.json", usage)

    return {
        "generation": gen,
        "idempotent_replay": False,
    }

def listProjects(api_key, status=None, query=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0222000" if __import__("os").path.isdir("./environment_mix/0222000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # Validate inputs
    if not isinstance(api_key, str) or not (1 <= len(api_key) <= 512):
        return _err("VALIDATION_ERROR", "Invalid api_key.")
    if status is not None and status not in ("active", "archived", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status.")
    if query is not None:
        if not isinstance(query, str) or not (1 <= len(query) <= 200):
            return _err("VALIDATION_ERROR", "Invalid query.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 200):
        return _err("VALIDATION_ERROR", "Invalid limit.")
    if cursor is not None:
        if not isinstance(cursor, str) or not (1 <= len(cursor) <= 512):
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    keys = _load("api_keys.json")
    projects = _load("projects.json")

    # Authenticate: match by id or by stored client-visible value (no plaintext exists for key_hash, so match id only)
    key_row = next((k for k in keys if k.get("id") == api_key), None)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key.")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked.")

    # Sort by created_at desc (best-effort parse)
    def _ts(p):
        s = p.get("created_at")
        if isinstance(s, str):
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    rows = list(projects)

    if status is not None:
        rows = [p for p in rows if p.get("status") == status]

    if query is not None:
        q = query.lower()
        def _s(x): return x if isinstance(x, str) else ""
        rows = [p for p in rows if (q in _s(p.get("name")).lower()) or (q in _s(p.get("description")).lower())]

    rows.sort(key=_ts, reverse=True)

    # Cursor is opaque; encode/decode as base64 JSON {"offset": int}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = obj["offset"]
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    return {
        "projects": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "server_time": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def createProject(api_key, name, description=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0222000" if __import__("os").path.isdir("./environment_mix/0222000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        raw = (uuid.uuid4().hex + uuid.uuid4().hex).upper()
        token = "".join(alphabet[ord(c) % len(alphabet)] for c in raw)[:20]
        return f"{prefix}_{token}"

    def _resolve_api_key_id(api_key_value):
        # Explicit credential parameter: authenticate by id OR by client-visible secret value if present.
        # Store only has key_hash; do NOT compare against it.
        keys = _load("api_keys.json")
        for r in keys:
            if r.get("id") == api_key_value:
                return r.get("id"), r
        # If the store had a plaintext column we'd check it; it doesn't, so id-match is the only viable auth here.
        return None, None

    def _append_usage(api_key_id, response_status):
        usage = _load("usage_events.json")
        ev = {
            "id": _new_id("ers_use"),
            "api_key_id": api_key_id,
            "generation_id": f"ers_gen_internal_{uuid.uuid4().hex.upper()}",
            "tool_name": "generateDiagram",
            "request_ts": now_iso,
            "response_status": response_status,
            "latency_ms": _lat_ms(),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(ev)
        _save("usage_events.json", usage)

    # Validate tool schema
    if not isinstance(api_key, str) or not (1 <= len(api_key) <= 512):
        _append_usage(None, "error")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string up to 512 characters.", field="api_key")
    if not isinstance(name, str) or not (1 <= len(name) <= 120):
        ak_id, _ = _resolve_api_key_id(api_key)
        _append_usage(ak_id, "error")
        return _err("VALIDATION_ERROR", "name must be a non-empty string up to 120 characters.", field="name")
    if description is not None:
        if not isinstance(description, str):
            ak_id, _ = _resolve_api_key_id(api_key)
            _append_usage(ak_id, "error")
            return _err("VALIDATION_ERROR", "description must be a string when provided.", field="description")
        if len(description) > 2000:
            ak_id, _ = _resolve_api_key_id(api_key)
            _append_usage(ak_id, "error")
            return _err("VALIDATION_ERROR", "description must be at most 2000 characters.", field="description")

    # Authenticate
    api_key_id, ak_row = _resolve_api_key_id(api_key)
    if not api_key_id:
        _append_usage(None, "error")
        return _err("UNAUTHORIZED", "Invalid API key.")

    # Enforce API key lifecycle
    if ak_row.get("status") != "active":
        _append_usage(api_key_id, "error")
        return _err("UNAUTHORIZED", "API key is not active.", field="api_key")

    # Enforce project constraints
    # - schema constraints: name length 1..200 (tool already restricts 1..120, ok)
    # - unique(name) where status != 'deleted'
    projects = _load("projects.json")
    for p in projects:
        if p.get("status") != "deleted" and isinstance(p.get("name"), str) and p.get("name") == name:
            _append_usage(api_key_id, "error")
            return _err(
                "CONFLICT",
                "Project constraint violated: unique(name) where status != 'deleted' (a non-deleted project with this name already exists).",
                field="name",
            )

    # Create
    proj = {
        "id": _new_id("ers_proj"),
        "name": name,
        "description": description,
        "status": "active",
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    projects.append(proj)
    _save("projects.json", projects)

    _append_usage(api_key_id, "accepted")
    return {"project": proj}

def updateProject(api_key, project_id, name=None, description=None, status=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0222000" if __import__("os").path.isdir("./environment_mix/0222000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        raw = (uuid.uuid4().hex + uuid.uuid4().hex).upper()
        token = "".join(alphabet[ord(c) % len(alphabet)] for c in raw)[:20]
        return f"{prefix}_{token}"

    def _resolve_api_key_id(api_key_value):
        keys = _load("api_keys.json")
        for r in keys:
            if r.get("id") == api_key_value:
                return r.get("id"), r
        return None, None

    def _append_usage(api_key_id, response_status):
        usage = _load("usage_events.json")
        ev = {
            "id": _new_id("ers_use"),
            "api_key_id": api_key_id,
            "generation_id": f"ers_gen_internal_{uuid.uuid4().hex.upper()}",
            "tool_name": "generateDiagram",
            "request_ts": now_iso,
            "response_status": response_status,
            "latency_ms": _lat_ms(),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(ev)
        _save("usage_events.json", usage)

    # Validate inputs (tool schema)
    if not isinstance(api_key, str) or not (1 <= len(api_key) <= 512):
        _append_usage(None, "error")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string up to 512 characters.", field="api_key")
    if not isinstance(project_id, str) or not re.match(r"^ers_proj_[0-9A-Z]{18,}$", project_id):
        ak_id, _ = _resolve_api_key_id(api_key)
        _append_usage(ak_id, "error")
        return _err("VALIDATION_ERROR", "project_id must match ^ers_proj_[0-9A-Z]{18,}$.", field="project_id")

    if name is not None:
        if not isinstance(name, str) or not (1 <= len(name) <= 120):
            ak_id, _ = _resolve_api_key_id(api_key)
            _append_usage(ak_id, "error")
            return _err("VALIDATION_ERROR", "name must be a non-empty string up to 120 characters.", field="name")
    if description is not None:
        if not isinstance(description, str):
            ak_id, _ = _resolve_api_key_id(api_key)
            _append_usage(ak_id, "error")
            return _err("VALIDATION_ERROR", "description must be a string when provided.", field="description")
        if len(description) > 2000:
            ak_id, _ = _resolve_api_key_id(api_key)
            _append_usage(ak_id, "error")
            return _err("VALIDATION_ERROR", "description must be at most 2000 characters.", field="description")
    if status is not None:
        if status not in ("active", "archived", "deleted"):
            ak_id, _ = _resolve_api_key_id(api_key)
            _append_usage(ak_id, "error")
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted.", field="status")

    # Must attempt a real mutation; require at least one change
    if name is None and description is None and status is None:
        ak_id, _ = _resolve_api_key_id(api_key)
        _append_usage(ak_id, "error")
        return _err("VALIDATION_ERROR", "At least one of name, description, or status must be provided.")

    # Authenticate
    api_key_id, ak_row = _resolve_api_key_id(api_key)
    if not api_key_id:
        _append_usage(None, "error")
        return _err("UNAUTHORIZED", "Invalid API key.")
    if ak_row.get("status") != "active":
        _append_usage(api_key_id, "error")
        return _err("UNAUTHORIZED", "API key is not active.", field="api_key")

    projects = _load("projects.json")
    idx = None
    for i, p in enumerate(projects):
        if p.get("id") == project_id:
            idx = i
            break
    if idx is None:
        _append_usage(api_key_id, "error")
        return _err("NOT_FOUND", "Project not found.", field="project_id")

    proj = projects[idx]

    # Cannot modify a deleted project (per tool description)
    if proj.get("status") == "deleted":
        _append_usage(api_key_id, "error")
        return _err("INVALID_TRANSITION", "Cannot modify a deleted project.", field="status")

    # Enforce lifecycle transitions when status changes
    transitions = {
        "active": {"archived", "deleted"},
        "archived": {"active", "deleted"},
        "deleted": set(),
    }
    if status is not None and status != proj.get("status"):
        cur = proj.get("status")
        if cur not in transitions or status not in transitions.get(cur, set()):
            _append_usage(api_key_id, "error")
            return _err(
                "INVALID_TRANSITION",
                f"Invalid status transition: {cur} -> {status}.",
                field="status",
            )

    # Enforce unique(name) where status != 'deleted' (for new name)
    if name is not None and name != proj.get("name"):
        for p in projects:
            if p.get("id") == project_id:
                continue
            if p.get("status") != "deleted" and p.get("name") == name:
                _append_usage(api_key_id, "error")
                return _err(
                    "CONFLICT",
                    "Project constraint violated: unique(name) where status != 'deleted' (a non-deleted project with this name already exists).",
                    field="name",
                )

    # Apply changes
    changed = False
    if name is not None and name != proj.get("name"):
        proj["name"] = name
        changed = True
    if description is not None and description != proj.get("description"):
        proj["description"] = description
        changed = True
    if status is not None and status != proj.get("status"):
        proj["status"] = status
        changed = True

    if not changed:
        # No success without effect
        _append_usage(api_key_id, "error")
        return _err("CONFLICT", "No changes to apply (fields match existing values).")

    proj["updated_at"] = now_iso
    projects[idx] = proj
    _save("projects.json", projects)

    _append_usage(api_key_id, "accepted")
    return {"project": proj}

def listDiagramGenerations(api_key, project_id, status=None, idempotency_key=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0222000" if __import__("os").path.isdir("./environment_mix/0222000") else "/app/database")
